```cpp
#include <iostream>
int AddPoint(int points) {
    return points + 1;
}
int main() {
int score = 0;
int turns = 2;
while (turns > 0) {
    score = AddPoint(score);
    turns = turns - 1;
}
std::cout << score << "\n";
    return 0;
}
```

The program prints 2. It starts at zero and saves one added point on each of two turns.
